 \subsection{Combining the $X$ and $Z$ measurements}
\label{sec:combining}

In this section our goal is to create a set of combined measurements
that simultaneously measure the approximately-commuting measurements
constructed in the previous section. We do this first for the points.
Recall that $\mH_\alice$ and $\mH_\bob$ denote the Hilbert spaces corresponding to
registers $\alice$ and $\bob$, respectively.

\begin{lemma}\label{lem:qld-4-10}
There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the following holds. 
	For every $x,z \in \F_q^m$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there are projective measurements $\{ \hat{Q}^{x,z}_{a,b} \}_{a,b \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that:
	\begin{enumerate}
		\item (\textbf{Self-consistency}) On average over uniformly random $x,z \in \F_q^m$,
		\begin{equation}
			\label{eq:qld-q-self-cons}
			(\hat{Q}^{x,z}_{a,b})_{\alice \alice'}  \approx_{\delta_Q} (\hat{Q}^{x,z}_{a,b})_{\bob \alice''}\,.
		\end{equation}

		\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $x,z \in \F_q^m$,
		\begin{gather}
			\label{eq:qld-q-cons-m-hat-xz}
				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_b)_{\bob \alice''}\;, \\
							\label{eq:qld-q-cons-m-hat-zx}
				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,Z),z}_b  \hat{M}^{(\Point,X),x}_{a} )_{\bob \alice''}\;.
		\end{gather}
              \end{enumerate}
                    Furthermore, all symmetric equivalents of these approximations
      also hold.
\end{lemma}

The construction of the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ whose existence is guaranteed in the lemma proceeds in three steps. In the first step, for every $(r,s)\in\F_q^2$ we combine the binary-outcome measurements $\hat{M}^{(\Point,X),x,r}_a$ and $\hat{M}^{(\Point,X),z,s}_b$; this is made possible by their approximate commutation as shown in Lemma~\ref{lem:qld-comm-cons}. In a second step, we show that the measurements thus constructed have a particular ``approximate linearity'' property, when seen as a function of the pair $(r,s)$. This allows us, in the third step, to combine them into a single measurement $\{ \hat{Q}^{x,z}_{a,b} \}$ with outcomes in $\F_q^2\cong \F_2^{2t}$ by applying the following  result from~\cite{NV17}:

	\begin{theorem}[Quantum linearity test]
	\label{thm:linearity}
		Let $0 \leq \delta \leq 1$, let $t$ be a positive integer, and let $\ket{\psi}$ be a state in a Hilbert space $\mathcal{H}_\alice \otimes \mathcal{H}_\bob$. Let $\{\mathcal{O}^u \}$ be a set of observables indexed by $u \in \F_2^t$ that act on $\mathcal{H}_\alice$. Suppose that on average over $u, u'$ chosen uniformly from $\F_2^t$, we have the following ``approximate linearity'' holds:
		\[
(\mathcal{O}^u \mathcal{O}^{u'})_{\alice} \approx_\delta (\mathcal{O}^{u+u'})_{\alice}
		\]
		where the $\approx$ statement is taken with respect to the state $\ket{\psi}$. 
Then there exists an extended state $\ket{\psi'}_{\alice \alice' \bob} = \ket{\psi}_{\alice \bob} \otimes \ket{0}_{\alice'}$ in an extended space $\mathcal{H}_{\alice} \otimes \mathcal{H}_\bob \otimes \mathcal{H}_{\alice'}$ and observables $\{ \mathcal{L}^u \}$ acting on $\mathcal{H}_\alice \otimes \mathcal{H}_{\alice'}$ such that for all $u, u' \in \F_2^t$, 
		\[
			\mathcal{L}^u \mathcal{L}^{u'} = \mathcal{L}^{u + u'} \qquad \text{and} \qquad (\mathcal{L}^u)_{\alice \alice'} \approx_\delta (\mathcal{O}^u)_\alice \,.
		\]
		Furthermore, the observable $\mathcal{L}^u = \Id$ when $u = 0$.
	\end{theorem}

		We now give the proof of Lemma~\ref{lem:qld-4-10}.

\begin{proof}[Proof of Lemma~\ref{lem:qld-4-10}]
For convenience in the proof we slightly abuse the notation $\approx_\delta$ to mean $\approx_{\poly(\eps)}$ for some polynomial function $\delta=\poly(\eps)$ that may differ each time the notation is used. 

\textbf{First step: construction of projective binary measurements $\{ \hat{R}^\omega_{a,b} \}$.}
	For every $\omega = (x,z,r,s)$ and $a,b \in \F_2$, define a measurement operator
	\[
		\hat{R}^\omega_{a,b} = \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a} \cdot \hat{M}^{(\Point,\zpt),z,s}_{b} \,.
	\]
	It is clear that $\{ \hat{R}^\omega_{a,b} \}_{a,b\in\F_2}$ is a POVM. Observe that on average over uniformly random $\omega$, 
	\begin{align}
	\label{eq:qld-r-2}
	\hat{R}^\omega_{a,b} \approx_{\sqrt{\delta_{\acom}}} \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a}\;,
	\end{align}
	which follows from the approximate commutation relation of Lemma~\ref{lem:qld-comm-cons} and the projectivity of $\{ \hat{M}^{(\Point,\zpt),z,s}_{b} \}$, together with Fact~\ref{fact:add-a-proj}. Next we show that $\{ \hat{R}^\omega_{a,b} \}$ is approximately self-consistent:  we aim to show that on average over $\omega$, it holds that $(\hat{R}^\omega_{a,b})_{\alice \alice'} \simeq_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}$ for some polynomial function $\delta = \poly(\eps)$. To show this, we perform the following calculation: (recall the state $\ket{\hat{\psi}}$ defined in~\eqref{eq:def-psihat})
	\begin{align}
		&\E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
		&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-1} \\
		&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-2} \\		
		&\approx_{\sqrt{\eps}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-3} \\
		&= \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
		&\approx_{\eps} \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-4} \\
		&= 1\;. \notag

#!/usr/bin/env python3
"""Check style conventions for changed paper-gap notes.

This is a local hook guard for ``docs/paper-gaps/*.tex`` notes.  The policy in
``docs/paper-gaps/policy.tex`` is intentionally mathematical rather than merely
syntactic, so this script does not try to certify the content of a note.  It
only catches structural mistakes that reviewers should not have to catch by
hand: missing front sections, missing shared macros and bibliography, and raw
inline traceability which should be expressed through the paper-gap macros.

The check is diff-scoped by default.  Existing archival notes are not reported
unless they are changed.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

PAPER_GAP_PREFIX = "docs/paper-gaps/"
EXCLUDED_NOTE_NAMES = {
    "command.tex",
    "policy.tex",
    "proof-gap-protocol.tex",
    "template.tex",
}

SECTION_RE = re.compile(r"\\section(?P<star>\*)?\{(?P<title>[^}]*)\}")
CITE_RE = re.compile(r"\\cite(?:\[[^\]]*\])?\{[^}]+\}")
XURL_RE = re.compile(r"\\usepackage(?:\[[^\]]*\])?\{[^}]*\bxurl\b[^}]*\}")
COMMAND_INPUT_RE = re.compile(r"\\input\{(?:\./)?command\}")
RAW_LEAN_ID_RE = re.compile(r"(?<!\\leanid\{)MIPStarRE\.[A-Za-z]")
RAW_PAPER_PATH_RE = re.compile(r"(?<!\\path\{)references/(?:ldt|qpbt|neexp)-paper/")
TEXTTT_TRACE_RE = re.compile(r"\\texttt\{(?:MIPStarRE|references/[a-z0-9-]+-paper)")


@dataclass(frozen=True)
class Finding:
    """A structural paper-gap-note style finding."""

    file: str
    message: str


def _is_note_file(rel_path: str) -> bool:
    """Return whether ``rel_path`` is a paper-gap note governed by the guard."""

    if not rel_path.startswith(PAPER_GAP_PREFIX) or not rel_path.endswith(".tex"):
        return False
    name = Path(rel_path).name
    return name not in EXCLUDED_NOTE_NAMES


def _changed_files_from_git(root: Path, *, base: str, staged: bool) -> list[str]:
    """Return changed files for either the staged index or a base revision."""

    command = ["git", "diff", "--name-only", "--diff-filter=ACMR"]
    if staged:
        command.append("--cached")
    else:
        command.append(base)
    command.append("--")
    proc = subprocess.run(
        command,
        cwd=root,
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr.strip() or "git diff failed")
    return [line.strip() for line in proc.stdout.splitlines() if line.strip()]


def _read_changed_files_file(path: Path) -> list[str]:
    """Read a newline-separated changed-file list."""

    return [line.strip() for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def _section_titles(text: str) -> list[tuple[str, bool]]:
    """Return section titles together with whether the section is starred."""

    return [
        (m.group("title").strip(), m.group("star") is not None)
        for m in SECTION_RE.finditer(text)
    ]


def _first_section_body(text: str) -> str:
    """Return the body of the first section, or the empty string if absent."""

    matches = list(SECTION_RE.finditer(text))
    if not matches:
        return ""
    start = matches[0].end()
    end = matches[1].start() if len(matches) > 1 else len(text)
    return text[start:end]


def _scan_note_text(rel_path: str, text: str) -> list[Finding]:
    """Return style findings for one paper-gap note."""

    findings: list[Finding] = []

    def add(message: str) -> None:
        findings.append(Finding(rel_path, message))

    if "\\documentclass" not in text:
        add("missing LaTeX document class")
    if not XURL_RE.search(text):
        add("missing `\\usepackage{xurl}`")
    if not COMMAND_INPUT_RE.search(text):
        add("missing shared paper-gap macros: `\\input{command}`")
    if "\\begin{document}" not in text or "\\end{document}" not in text:
        add("missing document body delimiters")

    sections = _section_titles(text)
    if len(sections) < 2:
        add("missing first two sections `At a glance` and `Key theorem forms`")
    else:
        first_title, first_starred = sections[0]
        second_title, second_starred = sections[1]
        if first_starred or first_title != "At a glance":
            add("Section 1 must be an unstarred `At a glance` section")
        if second_starred or not second_title.startswith("Key theorem forms"):
            add("Section 2 must be an unstarred `Key theorem forms` section")

    first_body = _first_section_body(text).lower()
    if first_body:
        if "difficulty" not in first_body:
            add("the `At a glance` section should state the difficulty")
        if "estimated weight" not in first_body:
            add("the `At a glance` section should state the estimated weight")
        if "mathlib/project split" not in first_body:
            add("the `At a glance` section should state the Mathlib/project split")
        has_key_inputs = (
            "key mathlib inputs" in first_body
            or "key mathematical inputs" in first_body
        )
        if not has_key_inputs:
            add(
                "the `At a glance` section should state the key Mathlib or "
                "mathematical inputs"
            )

    if "\\section{Conclusion}" not in text:
        add("missing `Conclusion` section")
    if "\\bibliographystyle{alpha}" not in text:
        add("missing `\\bibliographystyle{alpha}`")
    if "\\bibliography{references}" not in text:
        add("missing `\\bibliography{references}`")
    if not CITE_RE.search(text):
        add("missing bibliographic citation such as `\\cite{...}`")
    if ("\\ghissue{" not in text and "\\ghpr{" not in text
            and "\\localissue{" not in text):
        add("missing traceability macro `\\ghissue{...}`, `\\ghpr{...}`, "
            "or `\\localissue{...}`")

    if TEXTTT_TRACE_RE.search(text):
        add("use paper-gap macros instead of `\\texttt{...}` for Lean or source traceability")
    if RAW_LEAN_ID_RE.search(text):
        add("wrap fully qualified Lean names with `\\leanid{...}`")
    if RAW_PAPER_PATH_RE.search(text):
        add("wrap paper source paths with `\\path{...}`")

    return findings


def scan_changed_notes(root: Path, changed_files: list[str]) -> list[Finding]:
    """Return findings for changed paper-gap notes."""

    findings: list[Finding] = []
    for rel_path in sorted({path for path in changed_files if _is_note_file(path)}):
        path = root / rel_path
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        findings.extend(_scan_note_text(rel_path, text))
    return findings


def _parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path("."))
    parser.add_argument("--base", default="origin/main")
    parser.add_argument("--staged", action="store_true")
    parser.add_argument("--changed-files", nargs="*")
    parser.add_argument("--changed-files-file", type=Path)
    parser.add_argument("--ci", action="store_true")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = _parse_args(sys.argv[1:] if argv is None else argv)
    root = args.root.resolve()

    try:
        if args.changed_files_file is not None:
            changed_files = _read_changed_files_file(args.changed_files_file)
        elif args.changed_files is not None:
            changed_files = list(args.changed_files)
        else:
            changed_files = _changed_files_from_git(root, base=args.base, staged=args.staged)
    except RuntimeError as exc:
        print(f"check_paper_gap_note_style.py: {exc}", file=sys.stderr)
        return 2

    findings = scan_changed_notes(root, changed_files)
    if findings:
        print("Paper-gap note style findings:", file=sys.stderr)
        for finding in findings:
            print(f"  {finding.file}: {finding.message}", file=sys.stderr)
        return 1 if args.ci else 0

    if args.ci:
        checked = sum(1 for path in changed_files if _is_note_file(path))
        print(f"Paper-gap note style check passed for {checked} changed note(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

